import asyncio
import math


def configure(provider):
    s = provider.s
    loop = asyncio.get_running_loop()
    now = loop.time()
    budgets = {}
    for name in ('account', 'read', 'write'):
        limit = getattr_limit(s, name)
        window = getattr_window(s, name)
        mode = getattr_mode(s, name)
        budgets[name] = {
            'limit': limit, 'window': window * s.scale,
            'mode': mode, 'balance': float(limit),
            'stamp': now, 'generation': 0,
        }
    return {
        'condition': asyncio.Condition(), 'budgets': budgets,
        'blocked': dict.fromkeys(('account', 'read', 'write', 'concurrency'), now),
        'active': 0, 'queue': [], 'sequence': 0, 'pipeline': set(),
        'pipeline_limit': max(1, s.concurrency + math.ceil(s.write_limit)),
        'end': now + s.deadline * s.scale,
    }


def getattr_limit(s, name):
    return s.account_limit if name == 'account' else s.read_limit if name == 'read' else s.write_limit


def getattr_window(s, name):
    return s.account_window if name == 'account' else s.read_window if name == 'read' else s.write_window


def getattr_mode(s, name):
    return s.account_mode if name == 'account' else s.read_mode if name == 'read' else s.write_mode


def refresh(budget, now):
    elapsed = max(0.0, now - budget['stamp'])
    if budget['mode'] == 'token':
        budget['balance'] = min(budget['limit'], budget['balance'] + elapsed * budget['limit'] / budget['window'])
        budget['stamp'] = now
    elif elapsed >= budget['window']:
        periods = int(elapsed / budget['window'])
        budget['stamp'] += periods * budget['window']
        budget['generation'] += periods
        budget['balance'] = float(budget['limit'])


def budget_wait(budget, amount, now):
    if amount > budget['limit']:
        return math.inf
    if budget['balance'] >= amount:
        return 0.0
    if budget['mode'] == 'token':
        return (amount - budget['balance']) * budget['window'] / budget['limit']
    return max(0.0, budget['stamp'] + budget['window'] - now)


def eligibility(provider, ctx, entry, now):
    stage, job, cost, sequence = entry
    if ctx['active'] >= provider.s.concurrency:
        return math.inf
    if stage == 'read' and job not in ctx['pipeline'] and len(ctx['pipeline']) >= ctx['pipeline_limit']:
        return math.inf
    blocked = ctx['blocked']
    return max(
        0.0, blocked['account'] - now, blocked[stage] - now,
        blocked['concurrency'] - now,
        budget_wait(ctx['budgets']['account'], cost, now),
        budget_wait(ctx['budgets'][stage], 1, now),
    )


async def admit(provider, stage, job, ctx):
    condition = ctx['condition']
    cost = provider.s.read_cost if stage == 'read' else provider.s.write_cost
    async with condition:
        ctx['sequence'] += 1
        entry = (stage, job, cost, ctx['sequence'])
        ctx['queue'].append(entry)
        try:
            while True:
                now = asyncio.get_running_loop().time()
                if now >= ctx['end']:
                    return None
                for budget in ctx['budgets'].values():
                    refresh(budget, now)
                waits = [(candidate, eligibility(provider, ctx, candidate, now)) for candidate in ctx['queue']]
                ready = [candidate for candidate, delay in waits if delay <= 0.0]
                chosen = min(ready, key=lambda candidate: (candidate[0] != 'write', candidate[3])) if ready else None
                if chosen == entry:
                    charges = []
                    for name, amount in (('account', cost), (stage, 1)):
                        budget = ctx['budgets'][name]
                        budget['balance'] -= amount
                        charges.append((name, amount, budget['generation']))
                    ctx['active'] += 1
                    if stage == 'read':
                        ctx['pipeline'].add(job)
                    return charges
                positive = [delay for candidate, delay in waits if 0.0 < delay < math.inf]
                delay = min(positive + [ctx['end'] - now])
                try:
                    await asyncio.wait_for(condition.wait(), max(0.000001, delay))
                except asyncio.TimeoutError:
                    pass
        finally:
            ctx['queue'].remove(entry)
            condition.notify_all()


async def execute(provider, stage, job, ctx, charges, receipt, value):
    response = None
    try:
        response = await provider.request(
            stage, job, key='tempo-' + stage + '-' + str(job),
            receipt=receipt, value=value,
        )
        return response
    except asyncio.CancelledError:
        raise
    except Exception:
        return None
    finally:
        async with ctx['condition']:
            now = asyncio.get_running_loop().time()
            for budget in ctx['budgets'].values():
                refresh(budget, now)
            if response is not None and response.status == 429:
                # Rejected requests did not consume either quota.
                for name, amount, generation in charges:
                    budget = ctx['budgets'][name]
                    if budget['mode'] == 'token' or budget['generation'] == generation:
                        budget['balance'] = min(budget['limit'], budget['balance'] + amount)
                scope = response.scope
                if scope in ctx['blocked']:
                    until = now + max(0.0, response.retry_after) * provider.s.scale
                    ctx['blocked'][scope] = max(ctx['blocked'][scope], until)
            ctx['active'] -= 1
            ctx['condition'].notify_all()


async def call(provider, stage, job, ctx, receipt='', value=None):
    s = provider.s
    service = s.read_service if stage == 'read' else s.write_service
    timeout = max(0.25, s.slow_service * 1.25, service * 2.0) * s.scale
    for attempt in range(32):
        charges = await admit(provider, stage, job, ctx)
        if charges is None:
            return None
        # This task owns the slot until the actual request finishes, even if
        # its caller times out or is cancelled.
        task = asyncio.create_task(execute(provider, stage, job, ctx, charges, receipt, value))
        response = None
        for observation in range(32):
            remaining = ctx['end'] - asyncio.get_running_loop().time()
            if remaining <= 0:
                return None
            try:
                response = await asyncio.wait_for(asyncio.shield(task), min(timeout, remaining))
                break
            except asyncio.TimeoutError:
                continue
        else:
            return None
        if response is None:
            return None
        if response.status == 200:
            return response
        if response.status not in (429, 503):
            return None
        # 503 has consumed quota. Only this operation waits for its retry;
        # a 429 additionally installs its shared scope-specific cooldown.
        delay = max(0.0, response.retry_after) * s.scale
        remaining = ctx['end'] - asyncio.get_running_loop().time()
        if remaining <= delay:
            return None
        if delay:
            await asyncio.sleep(delay)
    return None


async def integrate(provider, job, ctx):
    try:
        read = await call(provider, 'read', job, ctx)
        if read is None:
            return False
        write = await call(provider, 'write', job, ctx, read.receipt, read.value * 3 + 7)
        return write is not None and write.status == 200
    finally:
        async with ctx['condition']:
            ctx['pipeline'].discard(job)
            ctx['condition'].notify_all()

