import asyncio
import math


def configure(provider):
    s = provider.s
    now = asyncio.get_running_loop().time()
    buckets = {}
    for name, limit, window, mode in (
        ('account', s.account_limit, s.account_window, s.account_mode),
        ('read', s.read_limit, s.read_window, s.read_mode),
        ('write', s.write_limit, s.write_window, s.write_mode),
    ):
        buckets[name] = {
            'limit': limit, 'window': window * s.scale,
            'mode': mode, 'balance': float(limit),
            'epoch': now, 'last': now, 'generation': 0,
        }
    return {
        'condition': asyncio.Condition(), 'buckets': buckets,
        'cooldown': dict.fromkeys(('account', 'read', 'write', 'concurrency'), 0.0),
        'active': 0, 'queue': [], 'sequence': 0, 'tasks': set(),
    }


def _refresh(bucket, now):
    if bucket['mode'] == 'token':
        elapsed = max(0.0, now - bucket['last'])
        bucket['balance'] = min(
            bucket['limit'],
            bucket['balance'] + elapsed * bucket['limit'] / bucket['window'],
        )
    else:
        generation = max(0, math.floor((now - bucket['epoch']) / bucket['window']))
        if generation > bucket['generation']:
            bucket['generation'] = generation
            bucket['balance'] = float(bucket['limit'])
    bucket['last'] = now


def _available_at(bucket, amount, now):
    if amount > bucket['limit']:
        return math.inf
    if bucket['balance'] >= amount:
        return now
    if bucket['mode'] == 'token':
        return now + (amount - bucket['balance']) * bucket['window'] / bucket['limit']
    return bucket['epoch'] + (bucket['generation'] + 1) * bucket['window']


async def _admit(provider, stage, ctx):
    s = provider.s
    cost = s.read_cost if stage == 'read' else s.write_cost
    condition = ctx['condition']
    async with condition:
        entry = (ctx['sequence'], stage, cost)
        ctx['sequence'] += 1
        ctx['queue'].append(entry)
        try:
            while True:
                now = asyncio.get_running_loop().time()
                for bucket in ctx['buckets'].values():
                    _refresh(bucket, now)
                if cost > ctx['buckets']['account']['limit'] or ctx['buckets'][stage]['limit'] < 1:
                    return None
                chosen = None
                wake = math.inf
                if ctx['active'] < s.concurrency:
                    for candidate in ctx['queue']:
                        sequence, endpoint, debit = candidate
                        ready = max(
                            now,
                            ctx['cooldown']['account'],
                            ctx['cooldown']['concurrency'],
                            ctx['cooldown'][endpoint],
                            _available_at(ctx['buckets']['account'], debit, now),
                            _available_at(ctx['buckets'][endpoint], 1, now),
                        )
                        wake = min(wake, ready)
                        if ready <= now:
                            rank = (0 if endpoint == 'write' else 1, sequence)
                            if chosen is None or rank < chosen[0]:
                                chosen = (rank, candidate)
                if chosen is not None and chosen[1] == entry:
                    ticket = []
                    for name, amount in (('account', cost), (stage, 1)):
                        bucket = ctx['buckets'][name]
                        bucket['balance'] -= amount
                        ticket.append((name, amount, bucket['generation']))
                    ctx['active'] += 1
                    return ticket
                if chosen is not None:
                    condition.notify_all()
                if math.isinf(wake) or wake <= now:
                    await condition.wait()
                else:
                    try:
                        await asyncio.wait_for(condition.wait(), max(0.000001, wake - now))
                    except asyncio.TimeoutError:
                        pass
        finally:
            ctx['queue'].remove(entry)
            condition.notify_all()


async def _request(provider, stage, job, ctx, ticket, receipt, value):
    response = None
    try:
        response = await provider.request(
            stage, job, key='tempo-' + stage + '-' + str(job),
            receipt=receipt, value=value,
        )
        return response
    finally:
        async with ctx['condition']:
            now = asyncio.get_running_loop().time()
            if response is not None and response.status == 429:
                # A rejected request debits neither budget. Refund only the
                # fixed-window generation in which the reservation was made.
                for name, amount, generation in ticket:
                    bucket = ctx['buckets'][name]
                    _refresh(bucket, now)
                    if bucket['mode'] == 'token' or bucket['generation'] == generation:
                        bucket['balance'] = min(bucket['limit'], bucket['balance'] + amount)
                scope = response.scope
                if scope not in ctx['cooldown']:
                    scope = 'account'
                ctx['cooldown'][scope] = max(
                    ctx['cooldown'][scope],
                    now + max(0.01, response.retry_after) * provider.s.scale,
                )
            ctx['active'] -= 1
            ctx['condition'].notify_all()


def _finished(ctx, task):
    ctx['tasks'].discard(task)
    if not task.cancelled():
        task.exception()


async def call(provider, stage, job, ctx, receipt='', value=None):
    s = provider.s
    initial_timeout = max(0.1, s.read_service, s.write_service, s.slow_service) * 1.25
    for attempt in range(32):
        ticket = await _admit(provider, stage, ctx)
        if ticket is None:
            return None
        task = asyncio.create_task(
            _request(provider, stage, job, ctx, ticket, receipt, value)
        )
        ctx['tasks'].add(task)
        task.add_done_callback(lambda done: _finished(ctx, done))
        response = None
        timeout = initial_timeout
        for observation in range(8):
            try:
                # Shielding preserves server work and its admission slot on
                # both timeout and cancellation of the integrating caller.
                response = await asyncio.wait_for(asyncio.shield(task), timeout * s.scale)
                break
            except asyncio.TimeoutError:
                if task.done():
                    # A TimeoutError raised by request itself is ambiguous;
                    # do not assume its server-side work has stopped.
                    return None
                timeout = min(initial_timeout * 8, timeout * 2)
        if response is None:
            return None
        if response.status == 200:
            return response
        if response.status == 429:
            continue
        if response.status != 503:
            return None
        # A 503 has already spent both quotas. Its delay applies to this
        # retry, without imposing an endpoint-wide outage on other jobs.
        await asyncio.sleep(max(0.01, response.retry_after) * s.scale)
    return None


async def integrate(provider, job, ctx):
    read = await call(provider, 'read', job, ctx)
    if read is None:
        return False
    write = await call(provider, 'write', job, ctx, read.receipt, read.value * 3 + 7)
    return write is not None and write.status == 200
